sys_ux_client_script.script:
/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 * @param {any} params.imports
 * @param {ApiHelpers} params.helpers
 */
function handler({
    api,
    event,
    helpers,
    imports
}) {
    var link = "/ann?id=attachment_viewer&attachment_id=" + api.state.selectedValue.value;
    //console.log("LINK - " + JSON.stringify(api.data.record.actions.items));
    api.setState("imageLink", link);
}
